  "npc_dialog_sq_lira_mon": {
    id: "npc_dialog_sq_lira_mon",
    displayName: "리라 몬 대기 대화",
    triggerKey: "manual",
    triggerTargetId: null,
    triggerRepeat: "repeat",
    maxLinesPerPage: 4,
    completionPolicy: "none",
    nextRoute: "/(game)/planet",
    skippable: true,
    typewriterSpeedMs: 80,
    fadeInEnabled: false,
    fadeInDurationMs: 0,
    fadeOutEnabled: false,
    fadeOutDurationMs: 0,
    pages: [
      {
        sceneId: "npc_dialog_sq_lira_mon",
        pageIndex: 0,
        label: "[ 리라 몬 ]",
        text: "오늘은 보고서 쓰러 온 게 아니잖아.\n칼 릿지 옆자리가 비어 있어.\n전과도 손실도 오늘은 세지 말자.",
        labelEn: "[ Lira Mon ]",
        textEn: "Today is not a sortie file.\nSit with Cal.\nThis is not a place to count the numbers.",
        imageAssetKey: "assets/images/npc/noname_char009.png",
        speakerNpcCaptainId: "npc_cpt_sq_lira_mon",
        viewMode: "ingame_dialog",
        textBoxPreset: "compact",
        imageScalePct: 100,
        actionLabel: null,
        actionLabelEn: null,
      },
      {
        sceneId: "npc_dialog_sq_lira_mon",
        pageIndex: 1,
        label: "[ 리라 몬 ]",
        text: "나는 이 관문 기록을 맡고 있어.\n여기선 다들 말을 아껴. 국경이니까.\n고향 얘기는 서로 묻지 않고.",
        labelEn: "[ Lira Mon ]",
        textEn: "I keep the Aura gate.\nI file the day in the language of the border.\nI will not open the Arcadia file.",
        imageAssetKey: "assets/images/npc/noname_char009.png",
        speakerNpcCaptainId: "npc_cpt_sq_lira_mon",
        viewMode: "ingame_dialog",
        textBoxPreset: "compact",
        imageScalePct: 100,
        actionLabel: null,
        actionLabelEn: null,
      },
      {
        sceneId: "npc_dialog_sq_lira_mon",
        pageIndex: 2,
        label: "[ 리라 몬 ]",
        text: "관문은 내가 닫을 테니 서두르지 마.\n우선 잔부터 내려놓고 앉아.\n정박 자리 소문은 칼 릿지가 알아.",
        labelEn: "[ Lira Mon ]",
        textEn: "I close the door later.\nSet the glass down first.\nCal knows the empty-berth rumor.",
        imageAssetKey: "assets/images/npc/noname_char009.png",
        speakerNpcCaptainId: "npc_cpt_sq_lira_mon",
        viewMode: "ingame_dialog",
        textBoxPreset: "compact",
        imageScalePct: 100,
        actionLabel: null,
        actionLabelEn: null,
      }
    ],
  },
